# Builds the `variable_dictionary` dataset (data/variable_dictionary.rda): the
# OECD Scale Up variable dictionary (Phase 3 spreadsheet: sheets BASE_FINANCIALS,
# PLANTS_RAW, TRADE_RAW), with two additions of this package: what the package
# does with each variable (`package_requirement`, `package_use`) and the money /
# negative-value flags the build applies. This script is the source of truth:
# edit the rows below, then re-run it from the package root
#   Rscript data-raw/variable_dictionary.R
# Priorities: the spreadsheet's fill colours (exit_acq and exit_close had their
# own colour; the OECD team classed them as first-order nice-to-have).

v <- function(dataset, variable, definition, format, priority, package_requirement, package_use,
              coding = "", source = "", sbs_code = "", notes = "", money = FALSE, negatives_missing = FALSE) {
  data.frame(dataset = dataset, variable = variable, definition = definition, format = format,
             coding = coding, source = source, sbs_code = sbs_code, priority = priority, notes = notes,
             package_requirement = package_requirement, package_use = package_use,
             money = money, negatives_missing = negatives_missing, stringsAsFactors = FALSE)
}
MUST <- "must-have"
NICE1 <- "nice-to-have, first order"
NICE2 <- "nice-to-have, second order"
NACE_DEF <- "core sector, %s, NACE Rev. 2 or Rev. 2.1 (or ISIC Rev. 4); not ISIC Rev. 3 or NACE Rev. 1.1"
