variable_dictionary <- do.call(rbind, rows)
variable_dictionary$file <- c(base_financials = "base_financials_<CT>.dta", plants_RAW = "plants_RAW_<CT>.dta",
                              trade_RAW = "trade_RAW_<CT>.dta")[variable_dictionary$dataset]
variable_dictionary <- variable_dictionary[c("dataset", "file", setdiff(names(variable_dictionary), c("dataset", "file")))]
stopifnot(!anyDuplicated(variable_dictionary[c("dataset", "variable")]))
variable_dictionary <- tibble::as_tibble(variable_dictionary)
save(variable_dictionary, file = "data/variable_dictionary.rda", compress = "bzip2", version = 2)
